package com.tuling.tim.server.web;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.ObjectNode; import com.tuling.tim.common.security.ConnectToken; import com.tuling.tim.server.message.*; import com.tuling.tim.server.route.RedisRouteService; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.socket.*; import org.springframework.web.socket.handler.TextWebSocketHandler; import java.util.UUID; import java.util.concurrent.ThreadPoolExecutor;
@Component public class ChatWebSocketHandler extends TextWebSocketHandler { final ObjectMapper j; final ReliableMessageService m; final RedisRouteService r; final ThreadPoolExecutor e; @Value("${tim.server.id:im-server-1}") String server; @Value("${tim.connect-token.secret:demo-only-change-me}") String secret; public ChatWebSocketHandler(ObjectMapper j,ReliableMessageService m,RedisRouteService r,ThreadPoolExecutor e){this.j=j;this.m=m;this.r=r;this.e=e;}
 public void afterConnectionEstablished(WebSocketSession s)throws Exception{try{ConnectToken.Claims c=ConnectToken.verify(q(s,"token"),server,secret,System.currentTimeMillis());long id=c.userId();s.getAttributes().put("userId",id);WebSocketSession old=WebSocketSessionRegistry.replace(id,s);if(old!=null&&old.isOpen())old.close();e.execute(()->r.online(id,UUID.randomUUID().toString(),System.currentTimeMillis()));send(s,"READY",n->{n.put("userId",id);n.put("serverId",server);});e.execute(()->{try{for(OfflineMessage x:m.pullOffline(id,0,100)){ObjectNode n=(ObjectNode)j.readTree(x.getBody());n.put("type","CHAT_MESSAGE");n.put("offline",true);n.put("deliveryCursor",x.getDeliveryCursor());s.sendMessage(new TextMessage(n.toString()));}}catch(Exception ignored){}});}catch(RuntimeException x){s.close(CloseStatus.POLICY_VIOLATION);}}
 protected void handleTextMessage(WebSocketSession s,TextMessage t)throws Exception{JsonNode n;try{n=j.readTree(t.getPayload());}catch(Exception x){error(s,"INVALID_JSON","非法 JSON");return;}String type=n.path("type").asText();long id=(Long)s.getAttributes().get("userId");if("CHAT_SEND".equals(type)){long to=n.path("receiverId").asLong();String c=n.path("content").asText("");if(to<=0||c.trim().isEmpty()||c.length()>65536){error(s,"INVALID_ARGUMENT","receiverId 或 content 无效");return;}ChatMessage x=new ChatMessage();x.setClientMessageId(n.path("clientMessageId").asText(UUID.randomUUID().toString()));x.setFromUserId(id);x.setToUserId(to);x.setContent(c);e.execute(()->{m.accept(x);try{send(s,"MESSAGE_ACCEPTED",z->{z.put("requestId",n.path("requestId").asText());z.put("messageId",x.getMessageId());z.put("status","SENT");});}catch(Exception ignored){}});}else if("MESSAGE_ACK".equals(type)){String mid=n.path("messageId").asText("");if(!mid.isBlank())e.execute(()->m.acknowledge(mid,id));}else error(s,"UNKNOWN_TYPE","未知消息类型");}
 public void afterConnectionClosed(WebSocketSession s,CloseStatus x){Object id=s.getAttributes().get("userId");if(id instanceof Long)WebSocketSessionRegistry.remove((Long)id,s);} private String q(WebSocketSession s,String k){String q=s.getUri().getQuery();if(q!=null)for(String p:q.split("&")){String[] a=p.split("=",2);if(a.length==2&&a[0].equals(k))return a[1];}return null;} private void send(WebSocketSession s,String type,java.util.function.Consumer<ObjectNode> c)throws Exception{if(!s.isOpen())return;ObjectNode n=j.createObjectNode();n.put("type",type);c.accept(n);s.sendMessage(new TextMessage(n.toString()));} private void error(WebSocketSession s,String c,String msg)throws Exception{send(s,"ERROR",n->{n.put("code",c);n.put("message",msg);});}}
